CREATE TABLE IF NOT EXISTS yield_assessments(position TEXT NOT NULL,id TEXT NOT NULL,claimId TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(position,id)) STRICT;
CREATE INDEX IF NOT EXISTS yield_assessment_claim ON yield_assessments(position,claimId);
CREATE TRIGGER IF NOT EXISTS yield_assessments_immutable_update BEFORE UPDATE ON yield_assessments WHEN NEW.data<>OLD.data OR NEW.id<>OLD.id OR NEW.position<>OLD.position OR NEW.claimId<>OLD.claimId BEGIN SELECT RAISE(ABORT,'immutable yield assessment'); END;
CREATE TRIGGER IF NOT EXISTS yield_assessments_immutable_delete BEFORE DELETE ON yield_assessments BEGIN SELECT RAISE(ABORT,'immutable yield assessment'); END;
CREATE TRIGGER IF NOT EXISTS yield_assessments_consistent BEFORE INSERT ON yield_assessments WHEN json_extract(NEW.data,'$.decimals') IS NOT NULL AND (EXISTS(SELECT 1 FROM yield_claims c WHERE c.position=NEW.position AND c.id=NEW.claimId AND json_extract(c.data,'$.decimals') IS NOT NULL AND json_extract(c.data,'$.decimals')<>json_extract(NEW.data,'$.decimals')) OR EXISTS(SELECT 1 FROM yield_assessments a WHERE a.position=NEW.position AND a.claimId=NEW.claimId AND json_extract(a.data,'$.decimals') IS NOT NULL AND json_extract(a.data,'$.decimals')<>json_extract(NEW.data,'$.decimals'))) BEGIN SELECT RAISE(ABORT,'yield metadata disagreement'); END;
